B.a1v=new A.f(B.f,["Cur\u0103\u021b\u0103 \u0219i taie cartofii","Spal\u0103 cartofii, cur\u0103\u021b\u0103 coaja \u0219i \xeendep\u0103rteaz\u0103 por\u021biunile deteriorate. Taie-i \xeen cuburi de aproximativ 2\u20133 cm. Nu combina buc\u0103\u021bi foarte mari cu unele foarte mici.","Cuburile au dimensiuni apropiate.","",0,B.c],t.M)
B.a27=new A.f(B.f,["Pune cartofii \xeen ap\u0103 rece","A\u0219az\u0103 cuburile \xeen oal\u0103 \u0219i acoper\u0103-le cu ap\u0103 rece. Adaug\u0103 sare dup\u0103 gust. Pune oala pe foc mediu-mare p\xe2n\u0103 \xeencepe s\u0103 fiarb\u0103.","Apa acoper\u0103 cartofii, iar ace\u0219tia au loc s\u0103 se mi\u0219te u\u0219or.","",0,B.c],t.M)
