B.a1C=new A.f(B.f,["Adaug\u0103 usturoiul la final","Pune usturoiul pisat \u0219i amestec\u0103 aproximativ 1 minut, c\xe2t s\u0103 \xee\u0219i elibereze aroma. Redu focul dac\u0103 este necesar, apoi opre\u0219te-l \u0219i presar\u0103 p\u0103trunjelul.","Usturoiul miroase pl\u0103cut \u0219i nu este \xeenchis la culoare.","",4,B.mF],t.M)
B.a2L=new A.f(B.f,["Gust\u0103 \u0219i serve\u0219te","Potrive\u0219te sarea \u0219i piperul, amestec\u0103 u\u0219or \u0219i transfer\u0103 ciupercile \xeen vasul de servire.","Ciupercile au o pelicul\u0103 de unt aromat, f\u0103r\u0103 usturoi ars.","",5,B.c],t.M)
