B.a1G=new A.f(B.f,["Pre\xeenc\u0103lze\u0219te cuptorul","Seteaz\u0103 cuptorul la aproximativ 205\xb0C \u0219i las\u0103-l s\u0103 ajung\u0103 la temperatur\u0103.","Indicatorul cuptorului arat\u0103 c\u0103 pre\xeenc\u0103lzirea s-a \xeencheiat.","",0,B.c],t.M)
B.a3l=new A.f(B.f,["Amestec\u0103 sosul","Combin\u0103 sm\xe2nt\xe2na, m\u0103rarul uscat, ceapa verde m\u0103run\u021bit\u0103, mu\u0219tarul \u0219i sucul de l\u0103m\xe2ie.","Sosul este omogen.","",1,B.c],t.M)
B.a0H=new A.f(B.f,["Preg\u0103te\u0219te tava \u0219i pe\u0219tele","Pulverizeaz\u0103 tava cu spray \u0219i a\u0219az\u0103 por\u021biile cu pielea \xeen jos. Spal\u0103 m\xe2inile \u0219i ustensilele dup\u0103 contactul cu pe\u0219tele crud.","Por\u021biile sunt separate, f\u0103r\u0103 suprapunere.","",2,B.c],t.M)
B.a30=new A.f(B.f,["Asezoneaz\u0103 \u0219i acoper\u0103","Presar\u0103 usturoiul pudr\u0103 \u0219i piperul m\u0103surat, apoi distribuie sosul deasupra por\u021biilor.","Fiecare bucat\u0103 are sos la suprafa\u021b\u0103.","",2,B.c],t.M)
