B.a03=new A.f(B.f,["Coace somonul","Pune tava \xeen cuptorul pre\xeenc\u0103lzit. Coace orientativ 20 de minute.","Pe\u0219tele devine opac \u0219i se desface \xeen fulgi.","",3,B.c4],t.M)
B.a1F=new A.f(B.f,["Verific\u0103 \u0219i serve\u0219te","M\u0103soar\u0103 centrul buc\u0103\u021bii celei mai groase. Continu\u0103 g\u0103tirea dac\u0103 nu a atins minimum 63\xb0C; apoi serve\u0219te.","Termometrul confirm\u0103 minimum 63\xb0C, indiferent de aspect.","",5,B.c],t.M)
