B.a1W=new A.f(B.f,["Preg\u0103te\u0219te carnea","Taie carnea \xeen cuburi de aproximativ 2\u20133 cm, pe un toc\u0103tor separat. Pune-o \xeen apa rece m\u0103surat\u0103, cu pu\u021bin\u0103 sare. Spal\u0103 m\xe2inile \u0219i ustensilele dup\u0103 contactul cu carnea crud\u0103.","Cuburile au m\u0103rimi apropiate.","",-1,B.c],t.M)
B.a3b=new A.f(B.f,["Porne\u0219te fierberea \u0219i spumeaz\u0103","\xcenc\u0103lze\u0219te la foc mediu. Adun\u0103 spuma pe m\u0103sur\u0103 ce apare, apoi redu focul la clocote mici.","Lichidul fierbe bl\xe2nd, f\u0103r\u0103 agita\u021bie puternic\u0103.","",0,B.c],t.M)
