B.a1T=new A.f(B.f,["Las\u0103 vita s\u0103 se fr\u0103gezeasc\u0103","Fierbe orientativ 60\u201380 de minute, apoi verific\u0103 un cub. Continu\u0103 dac\u0103 furculi\u021ba intr\u0103 greu. Completeaz\u0103 evaporarea cu ap\u0103 fierbinte, f\u0103r\u0103 s\u0103 dublezi cantitatea de lichid.","Carnea este aproape fraged\u0103 \xeenainte de ad\u0103ugarea legumelor.","",0,B.rP],t.M)
B.a10=new A.f(B.f,["Taie legumele","Toac\u0103 ceapa m\u0103runt, iar morcovul \u0219i p\u0103st\xe2rnacul cubule\u021be. Taie cartofii \xeen cuburi \u0219i fasolea verde \xeen buc\u0103\u021bi care \xeencap \xeen lingur\u0103.","Legumele sunt preg\u0103tite \xeen grupe, dup\u0103 ordinea ad\u0103ug\u0103rii.","",-1,B.c],t.M)
B.a0b=new A.f(B.f,["Adaug\u0103 r\u0103d\u0103cinoasele","Pune ceapa, morcovul \u0219i p\u0103st\xe2rnacul \xeen oal\u0103. G\u0103te\u0219te orientativ 15 minute, la foc mic spre mediu.","R\u0103d\u0103cinoasele \xeencep s\u0103 se \xeenmoaie.","",1,B.b7],t.M)
B.a02=new A.f(B.f,["G\u0103te\u0219te restul legumelor","Adaug\u0103 cartofii, fasolea verde \u0219i maz\u0103rea. Fierbe orientativ \xeenc\u0103 15 minute, apoi verific\u0103 fiecare: cartofii se str\u0103pung u\u0219or, p\u0103st\u0103ile \u0219i maz\u0103rea nu sunt tari. Continu\u0103 dac\u0103 este necesar.","Carnea \u0219i toate legumele sunt fragede.","",2,B.b7],t.M)
B.a12=new A.f(B.f,["Pune ro\u0219iile dup\u0103 cartofi","Adaug\u0103 ro\u0219iile pasate \u0219i las\u0103 ciorba s\u0103 revin\u0103 la fierbere bl\xe2nd\u0103.","Ro\u0219iile sunt amestecate uniform, iar cartofii erau deja p\u0103trun\u0219i.","",2,B.c],t.M)
B.a1n=new A.f(B.f,["Adaug\u0103 bor\u0219 dup\u0103 gust","D\u0103 bor\u0219ul \xeen clocot separat. Pune \xeen oal\u0103 doar o parte din cantitatea m\u0103surat\u0103, gust\u0103 \u0219i completeaz\u0103 treptat. Las\u0103 \xeenc\u0103 aproximativ 2 minute la fierbere bl\xe2nd\u0103.","Acreala este potrivit\u0103 pentru tine, f\u0103r\u0103 a domina supa.","",3,B.bS],t.M)
B.a2_=new A.f(B.f,["\xcencheie cu leu\u0219tean","Opre\u0219te focul, pune leu\u0219teanul sp\u0103lat \u0219i tocat \u0219i verific\u0103 sarea cu o lingur\u0103 r\u0103corit\u0103.","Legumele \xee\u0219i p\u0103streaz\u0103 forma, iar carnea se mestec\u0103 u\u0219or.","",4,B.c],t.M)
