B.a2B=new A.f(B.f,["Alege, spal\u0103 \u0219i \xeenmoaie fasolea","\xcendep\u0103rteaz\u0103 impurit\u0103\u021bile \u0219i boabele deteriorate. Spal\u0103 fasolea \u0219i acoper-o cu mult\u0103 ap\u0103 rece. Respect\u0103 eticheta; \xeen lipsa ei, las-o minimum 12 ore la frigider, \xeentr-un vas cu loc pentru umflare.","Boabele s-au hidratat \u0219i r\u0103m\xe2n acoperite cu ap\u0103.","",-1,B.rQ],t.M)
B.a2F=new A.f(B.f,["Schimb\u0103 apa \u0219i porne\u0219te fierberea","Arunc\u0103 apa de \xeenmuiere, cl\u0103te\u0219te boabele \u0219i pune ap\u0103 proasp\u0103t\u0103 suficient\u0103 s\u0103 le acopere. Adu la clocot.","Toat\u0103 cantitatea de fasole este \xeen ap\u0103 nou\u0103 care fierbe.","",-1,B.c],t.M)
