B.a1P=new A.f(B.f,["Cl\u0103te\u0219te lintea","\xcendep\u0103rteaz\u0103 impurit\u0103\u021bile, cl\u0103te\u0219te lintea \u0219i scurge-o.","Nu r\u0103m\xe2n impurit\u0103\u021bi vizibile.","",0,B.c],t.M)
B.a2o=new A.f(B.f,["Taie legumele","Toac\u0103 ceapa, morcovii \u0219i apio \xeen buc\u0103\u021bi mici; m\u0103run\u021be\u0219te usturoiul separat.","Buc\u0103\u021bile au dimensiuni apropiate.","",0,B.c],t.M)
B.a2c=new A.f(B.f,["\xcenmoaie baza","\xcenc\u0103lze\u0219te uleiul la foc mediu \u0219i g\u0103te\u0219te ceapa, morcovul \u0219i apio, amestec\xe2nd.","Ceapa este fraged\u0103, f\u0103r\u0103 por\u021biuni arse.","",1,B.c],t.M)
B.a1R=new A.f(B.f,["Adaug\u0103 aromele","Pune usturoiul, oregano, busuiocul \u0219i piperul. Amestec\u0103 aproximativ 2 minute.","Aromele sunt distribuite \u0219i usturoiul nu s-a ars.","",2,B.bS],t.M)
B.a2Z=new A.f(B.f,["Pune lintea \u0219i lichidele","Adaug\u0103 lintea, ro\u0219iile, supa de legume \u0219i apa m\u0103surate. Adu la fierbere.","Ingredientele sunt \xeen lichid fierbinte.","",3,B.c],t.M)
B.a2u=new A.f(B.f,["Fierbe p\xe2n\u0103 lintea este fraged\u0103","Redu focul, acoper\u0103 \u0219i fierbe cel pu\u021bin 60 de minute. Amestec\u0103 periodic \u0219i completeaz\u0103 cu ap\u0103 fierbinte dac\u0103 este necesar.","Boabele sunt moi; continu\u0103 dac\u0103 r\u0103m\xe2n tari.","",4,B.mE],t.M)
B.a2T=new A.f(B.f,["Gust\u0103 \u0219i por\u021bioneaz\u0103","Verific\u0103 gustul \xeenainte de a ad\u0103uga sare: supa de legume poate fi s\u0103rat\u0103. Por\u021bia sursei este aproximativ 240 ml.","Lintea este complet g\u0103tit\u0103.","",5,B.c],t.M)
